#!/usr/bin/env bash
# shellcheck disable=SC2034,SC1091
preflight(){ manifest=$1;secrets=$2;release=$3;absolute_file "$manifest";absolute_file "$secrets";[[ $release == /* && -d $release && ! -L $release ]]||return 1;provisioning="$(dirname "$secrets")/provisioning.json";absolute_file "$provisioning";[[ $(uname -m) == aarch64 ]]||return 1;source /etc/os-release;[[ $ID == ubuntu && $VERSION_ID == 24.04 ]]||return 1;[[ $(printf '%s\n' 22.13.0 "$(node --version|sed 's/^v//')"|sort -V|head -1) == 22.13.0 ]]||{ echo 'requires Node >=22.13' >&2;return 1;};[[ $(pnpm --version) == 9.12.3 ]]||{ echo 'requires pnpm 9.12.3' >&2;return 1;};[[ -f /opt/eduscope/models/vosk-model-en-us-0.22/am/final.mdl ]]||{ echo 'requires Vosk model artifact' >&2;return 1;};(( $(df -Pk "$release"|awk 'NR==2{print $4}')>=10485760 ))||return 1;local d=();[[ $EDUSCOPE_INSTALL_PROFILE == production ]]&&d=(--deployable);python3 "$release/scripts/bringup/validate-manifest.py" "$manifest" "${d[@]}";python3 "$release/deploy/runtime/render.py" --manifest "$manifest" --provisioning "$provisioning" --secrets "$secrets" --output-root /run/eduscope --profile "$EDUSCOPE_INSTALL_PROFILE" --check;if [[ $EDUSCOPE_INSTALL_PROFILE == production ]];then [[ -x /usr/libexec/eduscope-updater && -e /dev/disk/by-partlabel/eduscope-root-a && -e /dev/disk/by-partlabel/eduscope-root-b ]]||{ echo 'production requires accepted updater and A/B layout' >&2;return 1;};else echo 'placeholder / firmware acceptance still open';fi;release_id=$(git -C "$release" rev-parse HEAD);rollback_dir="/var/lib/eduscope/install/rollback/$(date -u +%Y%m%dT%H%M%SZ)-$$";fail_stage preflight; }
